import{_ as a,o as e,c as r,a4 as p}from"./chunks/framework.hWlsC8BY.js";const h=JSON.parse('{"title":"关于征集2027年智慧农业国家和行业标准制修订项目立项建议的通知","description":"","frontmatter":{"sidebar":false,"aside":false,"editLink":false,"lastUpdated":false,"prev":false,"next":false,"title":"关于征集2027年智慧农业国家和行业标准制修订项目立项建议的通知","date":"2026-09-24T00:00:00.000Z","source":"农业农村部智慧农业-标准规范","category":"standards","link":"https://www.moa.gov.cn/ztzl/zhnyzxd/bzgf/bzzj/202609/t20260924_6488088.htm","summary":"各有关单位:\\n为进一步完善智慧农业标准体系,加快制定“人工智能+农业”标准,有力保障智慧农业高质量发展,按照《智慧农业标准体系建设指南》要求,现面向各单位征集2027年智慧农业领域国家标准和行业标准制修订项目立项建议。有关事项通知如下。\\n一、征集原则\\n...\\n","contentHash":"9ce2c68e3967cbe25cbbd00ee340df2f","tags":["智慧农业","技术标准"]},"headers":[],"relativePath":"standards/2026-09-24-关于征集2027年智慧农业国家和行业标准制修订项目立项建议的通知.md","filePath":"standards/2026-09-24-关于征集2027年智慧农业国家和行业标准制修订项目立项建议的通知.md"}'),_={name:"standards/2026-09-24-关于征集2027年智慧农业国家和行业标准制修订项目立项建议的通知.md"};function s(n,t,o,d,l,c){return e(),r("div",null,[...t[0]||(t[0]=[p('<h1 id="关于征集2027年智慧农业国家和行业标准制修订项目立项建议的通知" tabindex="-1">关于征集2027年智慧农业国家和行业标准制修订项目立项建议的通知 <a class="header-anchor" href="#关于征集2027年智慧农业国家和行业标准制修订项目立项建议的通知" aria-label="Permalink to &quot;关于征集2027年智慧农业国家和行业标准制修订项目立项建议的通知&quot;">​</a></h1><blockquote><p>来源: <a href="https://www.moa.gov.cn/ztzl/zhnyzxd/bzgf/bzzj/202609/t20260924_6488088.htm" target="_blank" rel="noreferrer">农业农村部智慧农业-标准规范</a><br> 日期: 2026-09-24 摘要: 各有关单位: 为进一步完善智慧农业标准体系,加快制定“人工智能+农业”标准,有力保障智慧农业高质量发展,按照《智慧农业标准体系建设指南》要求,现面向各单位征集2027年智慧农业领域国家标准和行业标准制修订项目立项建议。有关事项通知如下。 一、征集原则 ...</p></blockquote><p>为进一步完善智慧农业标准体系,加快制定“人工智能+农业”标准,有力保障智慧农业高质量发展,按照《智慧农业标准体系建设指南》要求,现面向各单位征集2027年智慧农业领域国家标准和行业标准制修订项目立项建议。有关事项通知如下。</p><p>一、征集原则</p><p>以问题为导向,聚焦智慧农业技术落地和规模化应用中的突出短板与产业亟需,提出标准制修订项目建议;以协同为基础,引导产学研用等多元主体积极参与,凝聚广泛共识,形成标准研制与应用推广合力;以实效为根本,确保标准内容具备科学性、适用性和可操作性,有效支撑农业全产业链数字化转型升级,加快推进全流程“人工智能+”农业标准研制,促进人工智能技术安全、可靠、可控应用。</p><p>二、征集范围</p><p>根据“十五五”期间智慧农业领域标准化建设工作安排,2027年智慧农业领域标准制修订任务重点围绕以下内容:一是基础通用标准,包括农业人工智能术语、参考架构、测试评估等;二是关键技术标准,包括农业农村高质量数据集、知识图谱、大模型、智能体、具身智能、机器人等;三是应用场景标准,包括各应用场景技术规范、实施指南等;四是安全与伦理标准,包括科技伦理审查、农业人工智能安全防护要求等;五是其他智慧农业、农业人工智能发展亟需标准。</p><p>三、申报要求</p><p>(一)围绕征集范围自选申报内容。鼓励将经济、社会、生态效益显著并具备实施条件的科技成果,以及实施效果良好、符合标准制定需求和范围的农业农村地方标准和团体标准转化申报。</p><p>(二)项目建议应经过充分论证且具有相应的研究基础,立项依据充分,方案科学合理,草案成熟规范,应明确主要章节和主要技术内容,符合GB/T 1.1—2020《标准化工作导则 第1部分:标准化文件的结构和起草规则》要求。鼓励产学研用等单位联合申报。</p><p>(三)申报标准项目负责人及第一起草人应具有高级技术职称,熟练掌握标准制修订业务,如有标准相关培训证书,请提供扫描件。项目研制时间原则上不超过12个月。2026年以前已立项但未完成的项目负责人不得申报新项目。</p><p>(四)申报单位应通过全国标准信息公共服务平台(<a href="https://std.samr.gov.cn/" target="_blank" rel="noreferrer">https://std.samr.gov.cn/</a>)、全国农业食品标准公共服务平台(<a href="https://www.sdtdata.com/fx/fmoa/tsLibList" target="_blank" rel="noreferrer">https://www.sdtdata.com/fx/fmoa/tsLibList</a>)等对申报项目进行查重;与已发布、在研标准存在交叉、重叠的,不予受理。</p><p>(五)申报单位按照附件1、附件2编写项目申请书和标准文本草案,汇总并填写《2027年智慧农业国家和行业标准制修订项目立项建议一览表》(附件3)。</p><p>申报材料(盖章扫描件和可编辑电子版)请于2026年10月15日前发送至秘书处邮箱。</p><p>四、联系方式</p><p>联系人:任永好</p><p>电　话:010-59191675</p><p>电子邮箱:xxzxyjgh@163.com</p><p>农业农村部农业信息化标准化技术委员会</p><p>农业农村部信息中心(代章)</p><p>2026年9月23日</p><p><a href="https://www.moa.gov.cn/ztzl/zhnyzxd/bzgf/bzzj/202609/t20260924_6488088.htm" target="_blank" rel="noreferrer">阅读原文</a></p>',22)])])}const i=a(_,[["render",s]]);export{h as __pageData,i as default};
